const SAMPLE_PARTE_UUID = 'b2c3d4e5-f6a7-8901-bcde-f12345678901';

describe('formatBreadcrumb (Fase 2 — Title Case)', () => {
    it('maps canonical segments without ALL CAPS', () => {
        expect(formatBreadcrumb('juridico')).toBe('Jurídico');
        expect(formatBreadcrumb('due-diligence-2.0')).toBe('Pedências e Repactuações');
        expect(formatBreadcrumb('pos-aquisicao')).toBe('Pós-aquisição');
        expect(formatBreadcrumb('liquidacao-cessao')).toBe('Liquidação / Cessão');
    });

    it('falls back to Title Case with PT accents for unknown slugs', () => {
        expect(formatBreadcrumb('situacao-financeira')).toBe('Situação Financeira');
        expect(formatBreadcrumb('meu_segmento')).toBe('Meu Segmento');
        expect(formatBreadcrumb('calendario-operacional')).toBe('Calendário Operacional');
    });

    it('covers high-traffic editorial segments (inventory, not partial v1)', () => {
        expect(formatBreadcrumb('oficios')).toBe('Ofícios');
        expect(formatBreadcrumb('repactuacoes')).toBe('Repactuações');
        expect(formatBreadcrumb('operacoes-financeiras')).toBe('Operações financeiras');
        expect(formatBreadcrumb('politica-de-privacidade')).toBe('Política de privacidade');
        expect(formatBreadcrumb('gerencial-broker')).toBe('Gerencial Broker');
        expect(formatBreadcrumb('pos-precatorios')).toBe('Pós-precatórios');
    });

    it('never forces uppercase on the whole label', () => {
        const label = formatBreadcrumb('due-diligence-2.0');
        expect(label).not.toBe(label.toLocaleUpperCase('pt-BR'));
        expect(label).toBe('Pedências e Repactuações');
    });
});

describe('isEntityIdSegment / maskEntityIdHint', () => {
    it('detects UUID and long numeric ids', () => {
        expect(isEntityIdSegment(SAMPLE_DUE_UUID)).toBe(true);
        expect(isEntityIdSegment('123456')).toBe(true);
        expect(isEntityIdSegment('due-diligence-2.0')).toBe(false);
        expect(isEntityIdSegment('42')).toBe(false);
    });

    it('masks long ids for tooltips', () => {
        expect(maskEntityIdHint(SAMPLE_DUE_UUID)).toBe('a1b2c3d4…');
        expect(maskEntityIdHint('short')).toBe('short');
    });
});

describe('buildAppHeaderCrumbs', () => {
    it('builds Title Case crumbs for Due 2.0 path', () => {
        const crumbs = buildAppHeaderCrumbs(`/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}`, {
            dueNomeCredor: 'Maria Silva',
        });

        expect(crumbs).toHaveLength(3);
        expect(crumbs.every((c) => c.kind === 'crumb')).toBe(true);

        const labels = crumbs
            .filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb')
            .map((c) => c.label);

        expect(labels).toEqual(['Jurídico', 'Pedências e Repactuações', 'Maria Silva']);

